	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		EmailMessage
	 */
		public EmailMessage createEmailMessage( CreateEmailMessageCommand command ) {

		EmailMessage entity = new EmailMessage();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setEmailMessageId( command.getEmailMessageId() );
            entity.setSubject( command.getSubject() );
            entity.setBody( command.getBody() );
            entity.setSentAt( command.getSentAt() );
            entity.setMessageId( command.getMessageId() );
            entity.setDirection( command.getDirection() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of EmailMessage {0} ", entity.toString() );

		return entity;
	}

